mapper.update:
UPDATE job_schedules
SET schedule_date = #{scheduleDate}, start_time = #{startTime},
    end_time = #{endTime}, schedule_name = #{scheduleName}, slots_available = #{slotsAvailable},
    contact_name = #{contactName}, contact_phone = #{contactPhone},
    total_items = #{totalItems}, external_batch_id = #{externalBatchId}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM schedule_applications sa
WHERE sa.schedule_id = #{scheduleId}
AND sa.status = #{status}
